		private void ParseCsv()
		{
			if (!File.Exists("killer.ini"))
			{
				textBox1.Text += string.Format("Not found {0}\r\n", "killer.ini");
				textBox1.AppendText("----------------------------------------------------------------\r\n");
				return;
			}
			StreamReader streamReader = File.OpenText("killer.ini");
			textBox1.Text += string.Format("File {0} opened successfully\r\n", "killer.ini");
			string text = streamReader.ReadLine();
			if (text != null)
			{
				do
				{
					text = text.Trim();
					if (text.StartsWith("["))
					{
						prof_num++;
					}
					text = streamReader.ReadLine();
				}
				while (text != null);
			}
			uint num = prof_num;
			profiles = new PROFILES[num];
			int num2 = 0;
			if (0 < num)
			{
				do
				{
					profiles[num2] = new PROFILES();
					num2++;
				}
				while ((uint)num2 < prof_num);
			}
			streamReader.DiscardBufferedData();
			streamReader.BaseStream.Seek(0L, SeekOrigin.Begin);
			do
			{
				text = streamReader.ReadLine();
				text = text.Trim();
			}
			while (!text.StartsWith("["));
			int num3 = 0;
			if (0 < prof_num)
			{
				do
				{
					profiles[num3].Name = text.Substring(1, text.Length - 2);
					text = streamReader.ReadLine();
					if (text != null)
					{
						do
						{
							text = text.Trim();
							if (text.StartsWith("["))
							{
								break;
							}
							if (!text.StartsWith(";") && !string.IsNullOrEmpty(text))
							{
								profiles[num3].Num++;
							}
							text = streamReader.ReadLine();
						}
						while (text != null);
					}
					num3++;
				}
				while ((uint)num3 < prof_num);
			}
			int num4 = 0;
			if (0 < prof_num)
			{
				do
				{
					PROFILES obj = profiles[num4];
					obj.Cfg = new PROFILE[obj.Num];
					int num5 = 0;
					if (0 < profiles[num4].Num)
					{
						do
						{
							profiles[num4].Cfg[num5] = new PROFILE();
							num5++;
						}
						while ((uint)num5 < profiles[num4].Num);
					}
					num4++;
				}
				while ((uint)num4 < prof_num);
			}
			uint num6 = prof_num;
			textBox1.AppendText(string.Concat("Found " + num6, " profile(s)\r\n"));
			string[] separator = new string[1] { "," };
			streamReader.DiscardBufferedData();
			streamReader.BaseStream.Seek(0L, SeekOrigin.Begin);
			do
			{
				text = streamReader.ReadLine();
				text = text.Trim();
			}
			while (!text.StartsWith("["));
			for (int i = 0; (uint)i < prof_num; i++)
			{
				int num7 = 0;
				int num8 = 0;
				while (true)
				{
					text = streamReader.ReadLine();
					if (text == null)
					{
						break;
					}
					text = text.Trim();
					if (text.StartsWith("["))
					{
						break;
					}
					if (text.StartsWith(";") || string.IsNullOrEmpty(text))
					{
						continue;
					}
					num8++;
					string[] array = text.Split(separator, StringSplitOptions.None);
					if ((nint)array.LongLength != 9)
					{
						int num9 = num8;
						textBox1.AppendText(string.Concat(string.Concat(string.Concat("ERROR: In profile " + (i + 1), " line "), num9.ToString()), " with error(s)\r\n"));
						profiles[i].Num--;
						continue;
					}
					int num10 = 0;
					do
					{
						array[num10] = array[num10].Trim();
						char[] trimChars = new char[1] { '"' };
						array[num10] = array[num10].Trim(trimChars);
						if (num10 == 3 || (uint)(num10 - 5) <= 2u)
						{
							if (string.Compare(array[num10], "NULL", new CultureInfo("en-US"), CompareOptions.IgnoreCase) == 0)
							{
								array[num10] = "0";
							}
							else if (array[num10].StartsWith("0x"))
							{
								array[num10] = array[num10].Substring(2);
							}
						}
						num10++;
					}
					while (num10 < (nint)array.LongLength);
					profiles[i].Cfg[num7].Class = array[0];
					profiles[i].Cfg[num7].SubClass = array[1];
					profiles[i].Cfg[num7].Name = array[2];
					profiles[i].Cfg[num7].Address = Convert.ToUInt16(array[3], 16);
					if (string.Compare(array[4], "H1", new CultureInfo("en-US"), CompareOptions.IgnoreCase) == 0)
					{
						profiles[i].Cfg[num7].Type = 1;
						try
						{
							uint min = Convert.ToByte(array[5], 16);
							profiles[i].Cfg[num7].Min = min;
							uint max = Convert.ToByte(array[6], 16);
							profiles[i].Cfg[num7].Max = max;
							uint num11 = Convert.ToByte(array[7], 16);
							profiles[i].Cfg[num7].Default = num11;
						}
						catch (Exception)
						{
							int num12 = num8;
							textBox1.AppendText(string.Concat(string.Concat(string.Concat("ERROR: In profile " + (i + 1), " line "), num12.ToString()), " with error(s)\r\n"));
							profiles[i].Num--;
							continue;
						}
					}
					else if (string.Compare(array[4], "I1", new CultureInfo("en-US"), CompareOptions.IgnoreCase) == 0)
					{
						profiles[i].Cfg[num7].Type = 2;
						try
						{
							uint min2 = (uint)Convert.ToSByte(array[5], 10);
