		private void textBox_KeyDown_NUM(object __unnamed000, KeyEventArgs e)
		{
			nonNumberEntered = false;
			if ((e.KeyCode < Keys.D0 || e.KeyCode > Keys.D9) && (e.KeyCode < Keys.NumPad0 || e.KeyCode > Keys.NumPad9) && e.KeyCode != Keys.Back)
			{
				nonNumberEntered = true;
			}
			if (Control.ModifierKeys == Keys.Shift)
			{
				nonNumberEntered = true;
			}
		}

		private void textBox_KeyPress_NUM(object __unnamed000, KeyPressEventArgs e)
		{
			if (nonNumberEntered)
			{
				e.Handled = true;
			}
		}

		private void textBox_KeyPress_NUM_LETTERS(object __unnamed000, KeyPressEventArgs e)
		{
			sbyte keyChar = (sbyte)e.KeyChar;
			if ((keyChar < 65 || keyChar > 90) && (keyChar < 97 || keyChar > 122) && (keyChar < 48 || keyChar > 57) && keyChar != 8)
			{
				e.Handled = true;
			}
		}

		private void textBox_KeyPress_HEX(object __unnamed000, KeyPressEventArgs e)
		{
			sbyte keyChar = (sbyte)e.KeyChar;
			if ((keyChar < 48 || keyChar > 57) && (keyChar < 65 || keyChar > 70) && (keyChar < 97 || keyChar > 102) && keyChar != 8)
			{
				e.Handled = true;
			}
		}

