		private void dataGridView3_EditingControlShowing(object sender, DataGridViewEditingControlShowingEventArgs e)
		{
			e.Control.KeyPress += textBox_KeyPress_HEX;
		}

		private void dataGridView3_CellBeginEdit(object sender, DataGridViewCellCancelEventArgs e)
		{
			oldValue = dataGridView3.Rows[e.RowIndex].Cells[e.ColumnIndex].Value.ToString();
		}

		private void dataGridView3_CellEndEdit(object sender, DataGridViewCellEventArgs e)
		{
			string text = dataGridView3.Rows[e.RowIndex].Cells[e.ColumnIndex].Value.ToString().ToUpper();
			if (text.Length == 0)
			{
				dataGridView3.Rows[e.RowIndex].Cells[e.ColumnIndex].Value = oldValue;
				return;
			}
			if (text.Length == 1)
			{
				text = $"0{text}";
			}
			if (string.Compare(oldValue, text) == 0)
			{
				dataGridView3.Rows[e.RowIndex].Cells[e.ColumnIndex].Value = oldValue;
				return;
			}
			if (!Regex.IsMatch(text, "^[a-fA-F0-9]+$"))
			{
				dataGridView3.Rows[e.RowIndex].Cells[e.ColumnIndex].Value = oldValue;
				return;
			}
			dataGridView3.Rows[e.RowIndex].Cells[e.ColumnIndex].Value = text;
			Color red = Color.Red;
			dataGridView3.Rows[e.RowIndex].Cells[e.ColumnIndex].Style.BackColor = red;
		}

