		private void textBox_Enter(object sender, EventArgs e)
		{
			StrOldValue = ((TextBox)sender).Text.ToString();
		}

		private void textBox_TextChanged(object sender, EventArgs e)
		{
			string text = ((TextBox)sender).Text.ToString();
			if (text.Length == 0)
			{
				((TextBox)sender).Text = StrOldValue;
				return;
			}
			if (string.Compare(StrOldValue, text) == 0)
			{
				((TextBox)sender).Text = StrOldValue;
				return;
			}
			if (!Regex.IsMatch(text, "^[0-9]+$"))
			{
				((TextBox)sender).Text = StrOldValue;
				return;
			}
			ushort num = Convert.ToUInt16(((TextBox)sender).Text);
			if ((uint)num > 1000u)
			{
				MessageBox.Show("The range of values must be 0 - 1000", "ERROR", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				((TextBox)sender).Text = StrOldValue;
			}
		}

		private void textBox_Leave(object sender, EventArgs e)
		{
			string text = ((TextBox)sender).Text.ToString();
			if (text.Length == 0)
			{
				((TextBox)sender).Text = StrOldValue;
				return;
			}
			if (string.Compare(StrOldValue, text) == 0)
			{
				((TextBox)sender).Text = StrOldValue;
				return;
			}
			if (!Regex.IsMatch(text, "^[a-fA-F0-9]+$"))
			{
				((TextBox)sender).Text = StrOldValue;
				return;
			}
			byte b = Convert.ToByte(((TextBox)sender).Text, 16);
			if (b % 2 == 0 && b != 0)
			{
				if (((TextBox)sender).Text.Length % 2 == 1)
				{
					((TextBox)sender).Text = "0" + ((TextBox)sender).Text;
				}
			}
			else
			{
				MessageBox.Show("Please enter an integer between 0x02 and 0xFE", "ERROR", MessageBoxButtons.OK, MessageBoxIcon.Exclamation);
				((TextBox)sender).Text = StrOldValue;
			}
		}

		private void textBox79_Leave(object sender, EventArgs e)
		{
			string text = ((TextBox)sender).Text.ToString();
			if (text.Length != 0 && text.Length <= 2)
