		private void comboBox3_SelectedIndexChanged(object sender, EventArgs e)
		{
			dataGridView4.Rows.Clear();
			int selectedIndex = comboBox3.SelectedIndex;
			int num = 0;
			if (0 < profiles[selectedIndex].Num)
			{
				do
				{
					dataGridView4.Rows.Add();
					dataGridView4.Rows[num].Cells[0].Value = profiles[selectedIndex].Cfg[num].Class;
					dataGridView4.Rows[num].Cells[1].Value = profiles[selectedIndex].Cfg[num].SubClass;
					dataGridView4.Rows[num].Cells[2].Value = profiles[selectedIndex].Cfg[num].Name;
					ushort address = profiles[selectedIndex].Cfg[num].Address;
					dataGridView4.Rows[num].Cells[3].Value = address.ToString("X2");
					ushort address2 = profiles[selectedIndex].Cfg[num].Address;
					dataGridView4.Rows[num].Cells[3].ToolTipText = "0x" + address2.ToString("X2");
					switch (profiles[selectedIndex].Cfg[num].Type)
					{
					case 1:
					{
						dataGridView4.Rows[num].Cells[4].Value = "H1";
						dataGridView4.Rows[num].Cells[4].ToolTipText = "H1 = HEX 1 Byte";
						uint min = profiles[selectedIndex].Cfg[num].Min;
						dataGridView4.Rows[num].Cells[5].Value = min.ToString("X2");
						uint max = profiles[selectedIndex].Cfg[num].Max;
						dataGridView4.Rows[num].Cells[6].Value = max.ToString("X2");
						if (checkBox9.Checked)
						{
							byte b = (byte)profiles[selectedIndex].Cfg[num].Default;
							dataGridView4.Rows[num].Cells[7].Value = b.ToString("X2");
						}
						else
						{
							dataGridView4.Rows[num].Cells[7].Value = "-";
						}
						byte b2 = (byte)profiles[selectedIndex].Cfg[num].Default;
						dataGridView4.Rows[num].Cells[7].ToolTipText = "Default = " + b2.ToString("X2");
						break;
					}
					case 2:
						dataGridView4.Rows[num].Cells[4].Value = "I1";
						dataGridView4.Rows[num].Cells[4].ToolTipText = "I1 = Int8";
						dataGridView4.Rows[num].Cells[5].Value = (sbyte)profiles[selectedIndex].Cfg[num].Min;
						dataGridView4.Rows[num].Cells[6].Value = (sbyte)profiles[selectedIndex].Cfg[num].Max;
						if (checkBox9.Checked)
						{
							dataGridView4.Rows[num].Cells[7].Value = (sbyte)profiles[selectedIndex].Cfg[num].Default;
						}
						else
						{
							dataGridView4.Rows[num].Cells[7].Value = "-";
						}
						dataGridView4.Rows[num].Cells[7].ToolTipText = "Default = " + (sbyte)profiles[selectedIndex].Cfg[num].Default;
						break;
					case 3:
						dataGridView4.Rows[num].Cells[4].Value = "I2";
						dataGridView4.Rows[num].Cells[4].ToolTipText = "I2 = Int16";
						dataGridView4.Rows[num].Cells[5].Value = (short)profiles[selectedIndex].Cfg[num].Min;
						dataGridView4.Rows[num].Cells[6].Value = (short)profiles[selectedIndex].Cfg[num].Max;
						if (checkBox9.Checked)
						{
							dataGridView4.Rows[num].Cells[7].Value = (short)profiles[selectedIndex].Cfg[num].Default;
						}
						else
						{
							dataGridView4.Rows[num].Cells[7].Value = "-";
						}
						dataGridView4.Rows[num].Cells[7].ToolTipText = "Default = " + (short)profiles[selectedIndex].Cfg[num].Default;
						break;
					case 4:
						dataGridView4.Rows[num].Cells[4].Value = "U1";
						dataGridView4.Rows[num].Cells[4].ToolTipText = "U1 = UInt8";
						dataGridView4.Rows[num].Cells[5].Value = (byte)profiles[selectedIndex].Cfg[num].Min;
						dataGridView4.Rows[num].Cells[6].Value = (byte)profiles[selectedIndex].Cfg[num].Max;
						if (checkBox9.Checked)
						{
							dataGridView4.Rows[num].Cells[7].Value = (byte)profiles[selectedIndex].Cfg[num].Default;
						}
						else
						{
							dataGridView4.Rows[num].Cells[7].Value = "-";
						}
						dataGridView4.Rows[num].Cells[7].ToolTipText = "Default = " + (byte)profiles[selectedIndex].Cfg[num].Default;
						break;
					case 5:
