			dataGridView4.ClearSelection();
		}

		private void dataGridView4_EditingControlShowing(object sender, DataGridViewEditingControlShowingEventArgs e)
		{
			e.Control.KeyPress += KeyPress_dataGridView4;
		}

		private void KeyPress_dataGridView4(object sender, KeyPressEventArgs e)
		{
			int rowIndex = dataGridView4.CurrentCell.RowIndex;
			if (dataGridView4.Rows[rowIndex].Cells[4].Value.ToString().Equals("H1", StringComparison.OrdinalIgnoreCase))
			{
				sbyte keyChar = (sbyte)e.KeyChar;
				if (((keyChar < 48 || keyChar > 57) && (keyChar < 65 || keyChar > 70) && (keyChar < 97 || keyChar > 102) && keyChar != 8) || (((TextBox)sender).Text.Length >= 2 && keyChar != 8))
				{
					e.Handled = true;
				}
			}
			if ((dataGridView4.Rows[rowIndex].Cells[4].Value.ToString().Equals("I1", StringComparison.OrdinalIgnoreCase) || dataGridView4.Rows[rowIndex].Cells[4].Value.ToString().Equals("I2", StringComparison.OrdinalIgnoreCase)) && ((((uint)e.KeyChar < 48u || (uint)e.KeyChar > 57u) && e.KeyChar != '\b' && e.KeyChar != '-') || (e.KeyChar == '-' && ((TextBox)sender).Text.Length > 0)))
			{
				e.Handled = true;
			}
			if (dataGridView4.Rows[rowIndex].Cells[4].Value.ToString().Equals("U1", StringComparison.OrdinalIgnoreCase) || dataGridView4.Rows[rowIndex].Cells[4].Value.ToString().Equals("U2", StringComparison.OrdinalIgnoreCase) || dataGridView4.Rows[rowIndex].Cells[4].Value.ToString().Equals("U4", StringComparison.OrdinalIgnoreCase))
			{
				sbyte keyChar2 = (sbyte)e.KeyChar;
				if ((keyChar2 < 48 || keyChar2 > 57) && keyChar2 != 8)
				{
					e.Handled = true;
				}
			}
		}

